int jpc_atoaf(const char *s, int *numvalues, double **values) /* <=== jpc_atoaf */ 
{
	static const char delim[] = ", \t\n";
	char buf[4096];
	int n;
	double *vs;
	char *cp;

	strncpy(buf, s, sizeof(buf));
	buf[sizeof(buf) - 1] = '\0';
	n = 0;
	if ((cp = strtok(buf, delim))) {
		++n;
		while ((cp = strtok(0, delim))) {
			if (*cp != '\0') {
				++n;
			}
		}
	}

	if (n) {
		if (!(vs = jas_alloc2(n, sizeof(double)))) {
			return -1;
		}

		strncpy(buf, s, sizeof(buf));
		buf[sizeof(buf) - 1] = '\0';
		n = 0;
		if ((cp = strtok(buf, delim))) {
			vs[n] = atof(cp);
			++n;
			while ((cp = strtok(0, delim))) {
				if (*cp != '\0') {
					vs[n] = atof(cp);
					++n;
				}
			}
		}
	} else {
		vs = 0;
	}

	*numvalues = n;
	*values = vs;

	return 0;
}

void jas_free(void *ptr) /* <=== jas_free */ 
{
	JAS_DBGLOG(100, ("jas_free(%p)\n", ptr));
	free(ptr);
}

jas_tvparser_t *jas_tvparser_create(const char *s) /* <=== jas_tvparser_create */ 
{
	jas_tvparser_t *tvp;
	if (!(tvp = jas_malloc(sizeof(jas_tvparser_t)))) {
		return 0;
	}
	if (!(tvp->buf = jas_strdup(s))) {
		jas_tvparser_destroy(tvp);
		return 0;
	}
	tvp->pos = tvp->buf;
	tvp->tag = 0;
	tvp->val = 0;
	return tvp;
}

inline static bool jas_safe_size_mul(size_t x, size_t y, size_t *result) /* <=== jas_safe_size_mul */ 
{
#if defined(__clang__) || (defined(__GNUC__) && __GNUC__ > 5)
	size_t result_buffer;
	if (!result)
		result = &result_buffer;
	return !__builtin_mul_overflow(x, y, result);
#else
	/* Check if overflow would occur */
	if (x && y > SIZE_MAX / x) {
		/* Overflow would occur. */
		return false;
	}
	if (result) {
		*result = x * y;
	}
	return true;
#endif
}

void jpc_enc_cp_destroy(jpc_enc_cp_t *cp) /* <=== jpc_enc_cp_destroy */ 
{
	if (cp->ccps) {
		if (cp->tcp.ilyrrates) {
			jas_free(cp->tcp.ilyrrates);
		}
		jas_free(cp->ccps);
	}
	jas_free(cp);
}

const char *jas_tvparser_getval(const jas_tvparser_t *tvp) /* <=== jas_tvparser_getval */ 
{
	return tvp->val;
}

void jas_tvparser_destroy(jas_tvparser_t *tvp) /* <=== jas_tvparser_destroy */ 
{
