void *jas_alloc2(size_t num_elements, size_t element_size) /* <=== jas_alloc2 */ 
{
	size_t size;
	if (!jas_safe_size_mul(num_elements, element_size, &size)) {
		return 0;
	}
	return jas_malloc(size);
}

int jas_eprintf(const char *fmt, ...) /* <=== jas_eprintf */ 
{
	int ret;
	va_list ap;

	va_start(ap, fmt);
	ret = vfprintf(stderr, fmt, ap);
	va_end(ap);
	return ret;
}

unsigned jpc_floorlog2(uint_fast32_t x) /* <=== jpc_floorlog2 */ 
{
	int y;

	/* The argument must be positive. */
	assert(x > 0);

	y = 0;
	while (x > 1) {
		x >>= 1;
		++y;
	}
	return y;
}

int ratestrtosize(const char *s, uint_fast32_t rawsize, uint_fast32_t *size) /* <=== ratestrtosize */ 
{
	jpc_flt_t f;

	/* Note: This function must not modify output size on failure. */
	if (strchr(s, 'B')) {
		*size = atoi(s);
	} else {
		f = atof(s);
		if (f < 0) {
			*size = 0;
		} else if (f > 1.0) {
			*size = rawsize + 1;
		} else {
			*size = f * rawsize;
		}
	}
	return 0;
}

const jas_taginfo_t *jas_taginfo_nonull(const jas_taginfo_t *taginfo) /* <=== jas_taginfo_nonull */ 
{
	static const jas_taginfo_t invalidtaginfo = {
		-1, 0
	};

	return taginfo ? taginfo : &invalidtaginfo;
}

